//! Bundled branding generated by `scripts/render_logos.py`; no filesystem or
//! network lookups.
pub fn logo(dark: bool) -> &'static [u8] {
    if dark {
        include_bytes!("../../logo/whiteDraugr128.png")
    } else {
        include_bytes!("../../logo/blackDraugr128.png")
    }
}
pub fn window_icon() -> Result<iced::window::Icon, String> {
    let image = image::load_from_memory(app_icon())
        .map_err(|e| e.to_string())?
        .into_rgba8();
    iced::window::icon::from_rgba(image.into_raw(), 128, 128).map_err(|e| e.to_string())
}
/// Full-colour app icon (dark tile, bone skull, mint crown); generated by
/// `scripts/render_logos.py`.
pub fn app_icon() -> &'static [u8] {
    include_bytes!("../../logo/appIcon128.png")
}
/// One-colour tray glyph (crown on a clock), drawn natively at 32 px and
/// recoloured by tracking state.
pub fn tray_rgba(color: [u8; 3]) -> Vec<u8> {
    let mut rgba = image::load_from_memory(include_bytes!("../../logo/tray32.png"))
        .expect("bundled tray PNG")
        .into_rgba8()
        .into_raw();
    for pixel in rgba.as_chunks_mut::<4>().0 {
        pixel[..3].copy_from_slice(&color);
    }
    rgba
}
/// Tray colour while recording (brand mint, readable on dark and light panels).
pub const TRAY_RECORDING: [u8; 3] = [43, 181, 150];
/// Tray colour whenever nothing is being recorded (paused, stopped, error).
pub const TRAY_NOT_RECORDING: [u8; 3] = [213, 90, 70];
